observation.query:
SELECT DISTINCT ?graph ?subject ?predicate ?object
WHERE {
  VALUES ?graph {
    <urn:graphragprov:unit:u_2c1d06838958c6f4>
    <urn:graphragprov:unit:u_663251aba93d2da1>
    <urn:graphragprov:unit:u_94106360f6eaf3ec>
  }
  GRAPH ?graph {
    ?subject ?predicate ?object .
    FILTER(isIRI(?subject))
  }
}
ORDER BY ?graph ?subject ?predicate ?object
